// Reads the design tokens out of src/app/globals.css and writes src/config/design-tokens.ts, which the public
// design library (/design-library) shows and serves as tokens.css / tokens.json. Run after changing a token:
//   node scripts/design-tokens.mjs
// src/lib/design-tokens.test.ts fails if the generated file falls behind globals.css.
import { readFileSync, writeFileSync } from "node:fs";

const css = readFileSync("src/app/globals.css", "utf8");

/** Every custom property declared in a light-theme `:root` block, in file order. */
export function rootTokens(source) {
  const out = {};
  for (const block of source.matchAll(/(?:^|\n):root\s*\{([^}]*)\}/g)) {
    for (const d of block[1].matchAll(/--([a-z0-9-]+):\s*([^;]+);/g)) out[d[1]] = d[2].trim();
  }
  return out;
}

/** The part another app pastes in: Tailwind theme mapping, light tokens, base layer, icon font class, comment palette, easing. */
export function shareableCss(source) {
  const head = source.slice(0, source.indexOf('/* "What\'s new" sparkle'));
  const withoutDark = head.replace(/\n\.dark\s*\{[^}]*\}\n/, "\n").replace(/@custom-variant dark[^\n]*\n\n?/, "");
  const extras = [...source.matchAll(/\n(:root \{ --(?:comment-red|ease-out-soft)[^}]*\})/g)].map((m) => m[1]);
  return `/* Design & Concur by Harisumiran: design tokens for Tailwind CSS v4 + shadcn/ui. Generated from the app's globals.css. */\n${withoutDark.trim()}\n\n${extras.join("\n")}\n`;
}

if (process.argv[1]?.endsWith("design-tokens.mjs")) {
  const tokens = rootTokens(css);
  writeFileSync("src/config/design-tokens.ts", `// Generated by scripts/design-tokens.mjs from src/app/globals.css — do not edit by hand.
/** Light-theme design tokens (CSS custom properties without the leading "--"). */
export const TOKENS: Record<string, string> = ${JSON.stringify(tokens, null, 2)};

/** The stylesheet another Tailwind v4 + shadcn/ui app can paste in to get the same look. */
export const TOKENS_CSS = ${JSON.stringify(shareableCss(css))};
`);
  console.log(Object.keys(tokens).length, "tokens");
}
